@@ -0,0 +1,39 @@
+{
+  "name": "adocerb-vscode",
+  "displayName": "AsciiDoc ERB Template",
+  "description": "Syntax highlighting for AsciiDoc with ERB templating",
+  "version": "0.2.0",
+  "engines": {
+    "vscode": "^1.91.0"
+  },
+  "categories": [
+    "Programming Languages"
+  ],
+  "repository": {
+    "type": "git",
+    "url": "https://github.com/riscv/riscv-unified-db",
+    "directory": "adocerb"
+  },
+  "publisher": "HowerLimited",
+  "contributes": {
+    "languages": [
+      {
+        "id": "AsciiDoc (ERB)",
+        "extensions": [
+          ".adoc.erb"
+        ],
+        "configuration": "./language-configuration-adocerb.json"
+      }
+    ],
+    "grammars": [
+      {
+        "language": "AsciiDoc (ERB)",
+        "scopeName": "text.asciidoc.erb",
+        "path": "./syntaxes/adoc-ruby-injection.json",
+        "embeddedLanguages": {
+          "source.ruby": "ruby"
+        }
+      }
+    ]
+  }
+}

@@ -0,0 +1,81 @@
+{
+  "name": "Asciidoc (Ruby - ERB)",
+  "scopeName": "text.asciidoc.erb",
+  "fileTypes": ["adoc.erb"],
+  "injections": {
+    "L:text.asciidoc.erb": {
+      "patterns": [
+        {
+          "include": "#comment"
+        },
+        {
+          "include": "#tags"
+        }
+      ]
+    }
+  },
+  "patterns": [
+    {
+      "include": "text.asciidoc"
+    }
+  ],
+  "repository": {
+    "comment": {
+      "patterns": [
+        {
+          "begin": "<%+#",
+          "beginCaptures": {
+            "0": {
+              "name": "punctuation.definition.comment.begin.erb"
+            }
+          },
+          "end": "%>",
+          "endCaptures": {
+            "0": {
+              "name": "punctuation.definition.comment.end.erb"
+            }
+          },
+          "name": "comment.block.erb"
+        }
+      ]
+    },
+    "tags": {
+      "patterns": [
+        {
+          "comment": "ERB block",
+          "begin": "<%+(?!>)[-=]?",
+          "beginCaptures": {
+            "0": {
+              "name": "punctuation.section.embedded.begin.erb"
+            }
+          },
+          "end": "(-?)%>",
+          "endCaptures": {
+            "0": {
+              "name": "punctuation.section.embedded.end.erb"
+            },
+            "1": {
+              "name": "punctuation.whitespace.embedded.erb"
+            }
+          },
+          "name": "meta.embedded.block.erb",
+          "contentName": "source.ruby.embedded.erb",
+          "patterns": [
+            {
+              "captures": {
+                "1": {
+                  "name": "punctuation.definition.comment.erb"
+                }
+              },
+              "match": "(#).*?(?=-?%>)",
+              "name": "comment.line.number-sign.erb"
+            },
+            {
+              "include": "source.ruby"
+            }
+          ]
+        }
+      ]
+    }
+  }
+}

